// uBurst is HAND-ADDED, not from the exporter — re-apply if hero.js is regenerated.
// Everything the exporter shipped drives a SINE: raising uAmpAll makes a point wobble
// harder about where it already is, with no net travel. Fine for idle shimmer, useless
// for an exit — the scatter grew and grew and the cloud just sat there vibrating.
// uBurst displaces monotonically along the same outward direction, so points actually
// leave. Scaled per point by its hash so they don't all move in lockstep.
// Reveal stagger. HAND-ADDED, not from the exporter.
//
// SPREAD is how far apart the earliest and latest points are born, WINDOW is how long
// one point takes to go from invisible to solid. They should add up to 1.0 — that's
// the last point starting exactly as late as it can and still finishing on time.
//
// Trading one for the other is the whole dial: a wide spread with a narrow window
// means points blink in individually over a long period (very staggered), a narrow
// spread with a wide window means they all drift up together (barely staggered).
const REVEAL_SPREAD = 0.82;
const REVEAL_WINDOW = 0.18;

// A scatter of oversized points among the ones that drift. Hand-added, not from the
// exporter.
//
// The boost rides `aEdge` — the same weight `uAmp` rides — so it lands on the points
// that visibly orbit the silhouette. Spread evenly instead, the fattest dots sit in
// the middle of a face, where they read as scan artefacts rather than motion.
//
// SCATTER is the top slice of the hash that grows at all; BOOST is what the very
// largest reach, as a multiple of the resting size. smoothstep between them gives a
// spread of sizes rather than two discrete populations.
const SIZE_SCATTER = 0.19;
const SIZE_BOOST = 3.5;

const VERT = `
attribute float aEdge;
attribute float aAmbient;
uniform float uSize, uScale, uTime, uAmp, uAmpAll, uTwinkle, uSpeed, uBurst, uReveal;
uniform float uOrbit, uAmbientSize, uAmbientAlpha, uNearFade, uMaxSize;
uniform vec3 uBurstAxis, uOrbitC;
varying vec3 vCol;
varying float vAlpha;
float hash(vec3 p) { return fract(sin(dot(p, vec3(12.9898, 78.233, 37.719))) * 43758.5453); }
void main() {
  float ph = hash(position) * 6.2831853;
  vec3 p = position;
  // Ambient debris circles the scan's vertical axis. Each point keeps its own rate
  // (hash offset 3.1), so the shell shears as it turns instead of rotating rigidly —
  // a solid-body spin reads as the whole scene being on a turntable.
  if (aAmbient > 0.5) {
    float a = uTime * uOrbit * (0.45 + hash(position + 3.1) * 0.75);
    float ca = cos(a), sa = sin(a);
    vec3 rel = position - uOrbitC;
    p = uOrbitC + vec3(rel.x * ca - rel.z * sa, rel.y, rel.x * sa + rel.z * ca);
  }
  vec3 dir = normalize(position + vec3(1e-6));
  float amt = uAmpAll + uAmp * aEdge;
  if (amt > 0.0) {
    p += dir * (sin(uTime * uSpeed + ph) * amt);
    p.y += sin(uTime * uSpeed * 0.73 + ph * 1.7) * amt * 0.45;
    p.x += cos(uTime * uSpeed * 0.61 + ph * 2.3) * amt * 0.45;
  }
  if (uBurst > 0.0) {
    // Radial by default: every point leaves along its own outward direction, which
    // spreads the cloud sideways — ear to ear. Set uBurstAxis and they all travel
    // along ONE axis instead, so the cloud stretches front-to-back rather than
    // opening out. The intro uses the view axis for that; the exit leaves it zero
    // and keeps the radial blow-apart.
    vec3 bdir = dot(uBurstAxis, uBurstAxis) > 0.0 ? uBurstAxis : dir;
    // 0.55–1.45 of the burst, so the cloud opens out rather than expanding as a shell.
    p += bdir * (uBurst * (0.55 + hash(position + 1.7) * 0.9));
  }
  // Staggered reveal. uReveal walks 0 -> 1 across the intro; each point gets its own
  // birth threshold from its hash, so they solidify at different moments instead of
  // the whole cloud stepping up together. See REVEAL_SPREAD / REVEAL_WINDOW above.
  //
  // A DIFFERENT hash offset from the one the burst uses (5.3 vs 1.7), so how far a
  // point travels and when it appears are uncorrelated. Sharing an offset would tie
  // them together — the near points would also be the early ones, and the reveal
  // would read as a plane sweeping through rather than as a scatter.
  //
  // >= 1.0 short-circuits to fully opaque so the resting cloud costs nothing extra.
  vAlpha = 1.0;
  if (uReveal < 1.0) {
    float born = hash(position + 5.3) * ${REVEAL_SPREAD.toFixed(2)};
    vAlpha = clamp((uReveal - born) / ${REVEAL_WINDOW.toFixed(2)}, 0.0, 1.0);
  }
  // Debris sits back from the scan. It crosses the face with nothing to sort it in
  // front or behind (depthWrite is off), so at full opacity a passing speck reads as
  // a hole punched in him rather than something drifting past.
  if (aAmbient > 0.5) vAlpha *= uAmbientAlpha;
  float tw = 1.0;
  if (uTwinkle > 0.0) tw = 1.0 + uTwinkle * sin(uTime * uSpeed * 2.1 + ph * 3.7);
  vCol = color * tw;
  vec4 mv = modelViewMatrix * vec4(p, 1.0);
  gl_Position = projectionMatrix * mv;
  // The shell's near side passes very close to the camera — closer than the scan ever
  // gets, because the camera sits only just outside it — and point size goes as
  // 1/distance, so one of them projects as a dinner plate stuck to the lens. Fade it
  // out over the last stretch of its approach rather than clamping alone: a clamped
  // point is still a flat opaque disc sitting there, it just stops growing.
  if (aAmbient > 0.5) vAlpha *= smoothstep(uNearFade * 0.35, uNearFade, -mv.z);
  // Per-point size scatter. Its OWN hash offset (9.1), uncorrelated with the burst's
  // (1.7) and the reveal's (5.3) — share one and the big points are also the early
  // ones, which the eye picks out as a pattern immediately.
  float grow = smoothstep(${(1 - SIZE_SCATTER).toFixed(2)}, 1.0, hash(position + 9.1)) * aEdge;
  float sizeMul = 1.0 + grow * ${(SIZE_BOOST - 1).toFixed(2)};
  // Debris carries its own size spread. It can't use the boost above: that rides
  // aEdge, which is 0 out here, so every speck would land at exactly the resting size
  // and the shell would read as a uniform grid of dots laid over the scene.
  if (aAmbient > 0.5) sizeMul = uAmbientSize * (0.45 + hash(position + 9.1) * 1.70);
  gl_PointSize = uSize * sizeMul * (uScale / max(-mv.z, 0.0001)) * (1.0 + (tw - 1.0) * 0.6);
  // Backstop for the same case: the fade handles the approach, this catches anything
  // that slips past it (a resize mid-orbit re-solves the camera distance under it).
  if (aAmbient > 0.5) gl_PointSize = min(gl_PointSize, uMaxSize);
}`;

const FRAG = `
uniform float uRound, uContrast, uBright;
varying vec3 vCol;
varying float vAlpha;
void main() {
  if (uRound > 0.5 && length(gl_PointCoord - vec2(0.5)) > 0.5) discard;
  // Nothing to draw yet — cheaper than blending a fully transparent point.
  if (vAlpha <= 0.0) discard;
  vec3 c = (vCol - 0.5) * uContrast + 0.5 + uBright;
  gl_FragColor = vec4(clamp(c, 0.0, 1.0), vAlpha);
}`;

export async function createHero(container, binUrl = HERO_BIN_URL) {
  // A plain fetch, deliberately. This used to force revalidation with
  // `{cache: 'no-cache'}`, from when the binary was served under a fixed name and
  // a swapped-in cloud would otherwise keep rendering the old one out of cache.
  // The filename carries a content hash now, so a new binary is a new URL and
  // there is nothing stale to catch — while the revalidation itself would defeat
  // the <link rel="preload"> in head.twig, which is the whole point of preloading
  // 373kB that a dynamic import can't even ask for until it has parsed.
  // Mode and credentials have to keep matching that preload's `crossorigin`.
  // HAND-EDITED, not from the exporter — re-apply if hero.js is regenerated.
  const res = await fetch(binUrl);
  const buf = await res.arrayBuffer();
  const dv = new DataView(buf);
  if (dv.getUint32(0, false) !== 0x52334844) throw new Error("Not a hero.bin file");
  if (dv.getUint16(4, true) !== 2) throw new Error("Unsupported hero.bin version");
  const hasEdge = (dv.getUint16(6, true) & 1) === 1;
  const n = dv.getUint32(8, true);
  const lo = [dv.getFloat32(12, true), dv.getFloat32(16, true), dv.getFloat32(20, true)];
  const sc = [dv.getFloat32(24, true), dv.getFloat32(28, true), dv.getFloat32(32, true)];
  const HEAD = 36;
  // Positions are 16-bit offsets from the bounding box corner.
  const q = new Uint16Array(buf.slice(HEAD, HEAD + n * 6));
  const rgb = new Uint8Array(buf, HEAD + n * 6, n * 3);
  const ed = hasEdge ? new Uint8Array(buf, HEAD + n * 9, n) : null;
  const _tmpV = new THREE.Vector3(); // scratch for the bounds loops below
  const pos = new Float32Array(n * 3), col = new Float32Array(n * 3), edge = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    pos[i * 3] = lo[0] + q[i * 3] * sc[0];
    pos[i * 3 + 1] = lo[1] + q[i * 3 + 1] * sc[1];
    pos[i * 3 + 2] = lo[2] + q[i * 3 + 2] * sc[2];
    col[i * 3] = rgb[i * 3] / 255;
    col[i * 3 + 1] = rgb[i * 3 + 1] / 255;
    col[i * 3 + 2] = rgb[i * 3 + 2] / 255;
    edge[i] = ed ? ed[i] / 255 : 0;
  }

  // ── Ambient debris ────────────────────────────────────────────────────────
  // HAND-ADDED, not from the exporter — re-apply if hero.js is regenerated.
  //
  // A shell of points orbiting the scan, so the whole canvas carries motion and not
  // just the silhouette. They live in the SAME buffer as the scan rather than in a
  // second THREE.Points, for one reason: the material is transparent with depthWrite
  // off, so points composite in BUFFER ORDER and nothing occludes anything. A separate
  // object would draw entirely in front of the cloud or entirely behind it — a flat
  // starfield over the face, or a backdrop nothing ever crosses. Interleaved into one
  // buffer at a fixed stride, roughly half land in front of the face and half behind,
  // which is what makes it read as an orbit.
  //
  // They are kept OUT of every framing measurement. `pos` stays scan-only and is what
  // projectedBounds() walks; scanBox / scanRadius below are measured from it before
  // the shell exists. Let the shell into the fit and the solver zooms out to contain
  // it, shrinking the portrait to nothing.
  const AMBIENT_COUNT = 2600;
  const AMBIENT_NEAR = 1.05, AMBIENT_FAR = 2.30; // as multiples of the scan's radius
  const AMBIENT_RISE = 1.15;                     // taller than wide — the frame is portrait
  // What the specks are made of. "debris" lifts each one's colour from the scan, so
  // the shell reads as the cloud shedding material and the hero stays one effect.
  // "dust" gives them a pale neutral instead, unrelated to his palette, which reads as
  // air and depth — a separate layer the portrait sits inside. Colour is the ONLY
  // difference: everything else about the shell is shared, so the two are comparable.
  const AMBIENT_LOOK = "dust"; // "dust" | "debris"
  const AMBIENT_DUST = [0.910, 0.886, 0.835]; // #e8e2d5 — the site's cream, light 600
  // Each look carries its own weight, because they are not the same material. Dust is
  // air: finer and fainter, or it stops being atmosphere and becomes a dot screen over
  // the portrait. Debris is matter off the scan and can hold more presence. Sharing one
  // pair of numbers left whichever look wasn't tuned for looking wrong.
  const AMBIENT_TUNING = {
    dust:   { size: 0.55, alpha: 0.26 },
    debris: { size: 0.70, alpha: 0.78 },
  };
  const ambientTune = AMBIENT_TUNING[AMBIENT_LOOK];

  // The scan's own bounds, measured here so the shell can be placed around them and
  // the framing solver can read them back untouched.
  const scanBox = new THREE.Box3();
  for (let i = 0; i < pos.length; i += 3) {
    scanBox.expandByPoint(_tmpV.set(pos[i], pos[i + 1], pos[i + 2]));
  }
  const scanCentre = scanBox.getCenter(new THREE.Vector3());
  let scanRadius = 0;
  for (let i = 0; i < pos.length; i += 3) {
    scanRadius = Math.max(scanRadius, _tmpV.set(pos[i], pos[i + 1], pos[i + 2]).distanceTo(scanCentre));
  }

  const total = n + AMBIENT_COUNT;
  const posAll = new Float32Array(total * 3);
  const colAll = new Float32Array(total * 3);
  const edgeAll = new Float32Array(total);
  const ambAll = new Float32Array(total);
  // Every STRIDE-th slot is an ambient point, so the shell is spread evenly through
  // the draw order rather than sitting in a block at one end of it.
  const STRIDE = total / AMBIENT_COUNT;
  let si = 0, ai = 0;
  for (let i = 0; i < total; i++) {
    const wantAmbient = ai < AMBIENT_COUNT && (i >= ai * STRIDE || si >= n);
    if (wantAmbient) {
      // A direction on the unit sphere, then a radius out in the shell.
      const u = Math.random() * 2 - 1, th = Math.random() * Math.PI * 2;
      const r = Math.sqrt(1 - u * u);
      const rad = scanRadius * (AMBIENT_NEAR + Math.random() * (AMBIENT_FAR - AMBIENT_NEAR));
      posAll[i * 3] = scanCentre.x + Math.cos(th) * r * rad;
      posAll[i * 3 + 1] = scanCentre.y + u * rad * AMBIENT_RISE;
      posAll[i * 3 + 2] = scanCentre.z + Math.sin(th) * r * rad;
      if (AMBIENT_LOOK === "dust") {
        // One neutral, varied in BRIGHTNESS only. A hue spread would start arguing
        // with the olive; a flat single value reads as a printed halftone rather than
        // as air.
        const v = 0.70 + Math.random() * 0.42;
        colAll[i * 3] = Math.min(1, AMBIENT_DUST[0] * v);
        colAll[i * 3 + 1] = Math.min(1, AMBIENT_DUST[1] * v);
        colAll[i * 3 + 2] = Math.min(1, AMBIENT_DUST[2] * v);
      } else {
        // Two candidates, lighter one wins: the scan runs from pale shirt to near-black
        // hair, and a dark speck on the olive is invisible, so an even sample would
        // silently waste a third of the shell.
        const a = (Math.random() * n) | 0, b = (Math.random() * n) | 0;
        const src = (col[a * 3] + col[a * 3 + 1] + col[a * 3 + 2]) >= (col[b * 3] + col[b * 3 + 1] + col[b * 3 + 2]) ? a : b;
        colAll[i * 3] = col[src * 3];
        colAll[i * 3 + 1] = col[src * 3 + 1];
        colAll[i * 3 + 2] = col[src * 3 + 2];
      }
      edgeAll[i] = 0; // no silhouette drift: the orbit below is their motion
      ambAll[i] = 1;
      ai++;
    } else {
      posAll[i * 3] = pos[si * 3];
      posAll[i * 3 + 1] = pos[si * 3 + 1];
      posAll[i * 3 + 2] = pos[si * 3 + 2];
      colAll[i * 3] = col[si * 3];
      colAll[i * 3 + 1] = col[si * 3 + 1];
      colAll[i * 3 + 2] = col[si * 3 + 2];
      edgeAll[i] = edge[si];
      si++;
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.BufferAttribute(posAll, 3));
  geo.setAttribute("color", new THREE.BufferAttribute(colAll, 3));
  geo.setAttribute("aEdge", new THREE.BufferAttribute(edgeAll, 1));
  geo.setAttribute("aAmbient", new THREE.BufferAttribute(ambAll, 1));

  const mat = new THREE.ShaderMaterial({
    uniforms: {
      uSize:     { value: 0.009 },
      uScale:    { value: container.clientHeight * 0.5 },
      uRound:    { value: 1 },
      uTime:     { value: 0 },
      uAmp:      { value: 0.06 },
      uAmpAll:   { value: 0 },
      uTwinkle:  { value: 0.02 },
      uBurst:    { value: 0 }, // hand-added: monotonic outward travel, driven by the warp
      // Zero = travel radially (the exit's blow-apart). Non-zero = travel along this
      // one axis (the intro's front-to-back assemble). Hand-added.
      uBurstAxis: { value: new THREE.Vector3(0, 0, 0) },
      // Ambient debris (hand-added). uOrbitC is the axis it turns about — filled in
      // once the scan's centre is known, a few lines below.
      uOrbit:        { value: 0.055 }, // radians/sec at the median rate: ~2min a lap
      uAmbientSize:  { value: ambientTune.size },  // of the scan's resting point size
      uAmbientAlpha: { value: ambientTune.alpha },
      uOrbitC:       { value: new THREE.Vector3() },
      uNearFade:     { value: 0 },  // set from the scan's radius once it's measured
      uMaxSize:      { value: 14 }, // device px, before pixel ratio
      uContrast: { value: 1.2 },
      uBright:   { value: -0.13 },
      uSpeed:    { value: 0.25 },
      // 1 = every point solid. The intro walks this 0 -> 1 so points materialise as
      // they fly in, each on its own hash-derived threshold. Hand-added.
      uReveal:   { value: 1 }
    },
    // `transparent` so the reveal's per-point alpha is actually blended — without it
    // the fragment alpha is ignored and points snap from discarded to solid.
    //
    // depthWrite off with it: transparent points are drawn in buffer order, not
    // sorted back-to-front, so a nearer point written to the depth buffer while still
    // faint would punch a hole in whatever solid point lands behind it later. The
    // cloud is a shell of same-coloured points, so losing depth ordering costs
    // nothing visible — a hole would have been obvious.
    transparent: true,
    depthWrite: false,
    vertexShader: VERT, fragmentShader: FRAG, vertexColors: true
  });

  mat.uniforms.uOrbitC.value.copy(scanCentre);
  // Debris is fully solid once it is this far down the view axis, and gone by ~a third
  // of it. Scaled off the scan's own radius so it tracks the camera distance, which is
  // solved from the same number.
  mat.uniforms.uNearFade.value = scanRadius * 1.25;

  const scene = new THREE.Scene();
  const points = new THREE.Points(geo, mat);
  // The geometry's own bounding sphere would be the SCAN's (set above), while the
  // ambient shell reaches more than twice as far — three would cull the whole object
  // the moment that small sphere left the frustum. Nothing here is ever off-camera
  // anyway: the camera orbits this exact cloud and always looks at it.
  points.frustumCulled = false;
  scene.add(points);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  // The olive slab IS this clear colour: the section behind the canvas has no
  // background of its own, and the canvas is opaque (alpha: false). Kept in a
  // function because it has to be applied twice — here, and again after the GPU
  // context comes back. macOS sleep, an idle tab, a GPU reset: the browser drops
  // the context and later restores it, and three (r184) rebuilds its state on
  // restore with a fresh background whose clear colour is the default black. The
  // points re-upload and draw fine — so the portrait came back on a black slab.
  const applyClearColor = () => renderer.setClearColor(new THREE.Color("#4a5030"), 1);
  applyClearColor();
  const onContextRestored = () => applyClearColor();
  // Three's own restore handler runs first (it registered at construction), so by
  // the time this fires the state has been rebuilt and the colour can be re-set.
  renderer.domElement.addEventListener('webglcontextrestored', onContextRestored);
  // Fades in on its first drawn frame, so the cloud resolves rather than appearing
  // between one frame and the next — it can't be attached before the binary has been
  // fetched and unpacked, so there's always a beat where the slab is empty.
  //
  // Waiting for the FIRST FRAME, not for the mount: a canvas attached but not yet
  // drawn is an empty rectangle, and fading that in just delays the blink.
  //
  // Short, because the page's own arrival warp is usually still running underneath —
  // a long fade on top of that reads as the cloud lagging behind the page.
  // Very short now: the per-point reveal (uReveal) does the actual materialising, and
  // a 300ms blanket fade on top of it just fought the stagger — every point rising
  // together underneath the one that was supposed to make them arrive separately.
  // This is only here to cover the very first frame, so the canvas can't flash.
  renderer.domElement.style.opacity = "0";
  renderer.domElement.style.transition = "opacity 80ms linear";
  container.appendChild(renderer.domElement);

  const camera = new THREE.PerspectiveCamera(50, 1, 0.001, 100);
  // The exporter's look-at point. Superseded by `frameTarget` below, which centres on
  // the cloud itself — kept only so a regenerated file's value is easy to compare.
  const target = new THREE.Vector3(-0.25344, -0.13721, -0.55214); // eslint-disable-line no-unused-vars
  const R_EXPORTED = 1.08868, PHI = 1.45680;
  // Yaw, in radians. HAND-TUNED past the exporter's 0.75073 to turn the face a little
  // further toward the viewer — lower brings it round to camera, higher turns it away.
  const BASE = 0.67;
  // Yaw the warp turns to. Declared up here with BASE, not down in the warp block,
  // because the framing solve below needs it — it centres the cloud for BOTH angles.
  const WARP_FACE_ON = 0.00; // lower is more square to camera
  // HAND-EDITED, not from the exporter — re-apply if hero.js is regenerated.
  // The exporter left this "off" with a 5° arc. A slow, shallow sweep either side of
  // BASE reads as the subject being alive rather than as camera movement.
  //
  // ARC is the swing EITHER SIDE of BASE, so the full left-to-right travel is double
  // it: 4° here = ~8° end to end. SPEED feeds `sin(t * 0.5 * SPEED)`, so the cycle is
  // 2π / (0.5 * SPEED) seconds — 0.55 gives a little under 23s per round trip. Both
  // are one-number changes if it wants to be more or less noticeable.
  //
  // Started at 1.25°/0.4 and was dialled up from there. It can go further: on any
  // landscape frame the cloud is nowhere near the left and right edges (the fit binds
  // on HEIGHT), and even a 5° swing only reaches 0.972 of the way to the frame edge.
  // A narrow window is the one that runs out of room, and solvePointerHeadroom below
  // measures that and scales this back rather than letting it clip.
  //
  // Starts at BASE (sin 0 = 0), so there's no jump on load. The warp overrides theta
  // outright, which discards up to a full ARC of sweep at the moment it fires — still
  // small enough not to read as a snap.
  const MOTION = "sweep";
  const ARC = 0.0698, SPEED = 0.55; // 4° either side; ~23s per cycle

  // ── Height fit ────────────────────────────────────────────────────────────
  // HAND-EDITED, not from the exporter — re-apply if hero.js is regenerated.
  //
  // The exported radius framed the cloud as it sat in the Record3D viewer, which left
  // the subject floating small in the middle of a full-height section. This pulls the
  // camera in until the cloud fills the frame vertically without clipping.
  //
  // The camera ORBITS AND LOOKS AT the cloud's own centre, not the exported `target`,
  // which sits about a third of a unit off it — looking at a point to one side puts
  // the cloud off-centre and clips whatever falls past the edge.
  //
  // The distance is MEASURED, not predicted. Deriving it from the cloud's world-space
  // height — (height/2)/tan(fov/2) — assumes you're looking straight down an axis at a
  // flat object. This camera views from about 50° and the cloud is 0.2 units deep, so
  // perspective makes the near points project larger than their world offset implies:
  // the true on-screen height is bigger than the bounding box suggests, and the head
  // clipped top and bottom. Instead: project every point, find how far the furthest
  // reaches up or down the frame, and scale the distance by exactly that overshoot.
  // On-screen size is proportional to 1/distance, so each pass lands very close and a
  // couple of passes settle it.
  // CENTRING IS DONE IN SCREEN SPACE, not world space. The cloud's world X extent is
  // near enough symmetric (-0.229 to 0.223), so pointing the camera at its centre
  // ought to centre it — but the camera views from about 50°, which turns depth into
  // horizontal displacement. Points further from the camera sit nearer the middle of
  // the frame than their world position suggests, and the composition came out
  // right-heavy. So each pass measures where the cloud actually lands on screen and
  // slides the look-at point until the margins match.
  // NOT geo.computeBoundingBox() / computeBoundingSphere(): the geometry now carries
  // the ambient shell as well, and every number here has to describe the SCAN alone.
  // scanBox and scanRadius were measured from `pos` before the shell was generated.
  const frameTarget = new THREE.Vector3();
  scanBox.getCenter(frameTarget);
  // Start from the bounding sphere, which can't clip whatever the view angle — the
  // measured passes then tighten it to what's actually on screen.
  const cloudRadius = scanRadius;

  // 1 touches top and bottom exactly. Under 1 leaves margin — a point has size, which
  // the geometry doesn't account for, so the very topmost one would sit half cut.
  const FILL = 0.96;
  const FIT_PASSES = 4;

  let R = R_EXPORTED;

  // Where the cloud lands on screen, in normalised device coordinates: -1 is the left
  // or bottom edge, +1 the right or top.
  const _v = new THREE.Vector3();
  const _m = new THREE.Matrix4();
  function projectedBounds() {
    camera.updateMatrixWorld();
    _m.multiplyMatrices(camera.projectionMatrix, camera.matrixWorldInverse);
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    for (let i = 0; i < pos.length; i += 3) {
      _v.set(pos[i], pos[i + 1], pos[i + 2]).applyMatrix4(_m);
      if (_v.x < minX) minX = _v.x;
      if (_v.x > maxX) maxX = _v.x;
      if (_v.y < minY) minY = _v.y;
      if (_v.y > maxY) maxY = _v.y;
    }
    return {minX, maxX, minY, maxY};
  }

  const _right = new THREE.Vector3();
  const _up = new THREE.Vector3();

  // Solved per view ANGLE, because both answers depend on it: turning the camera
  // changes which points sit at the frame's edges, so the distance that fits and the
  // look-at point that centres are different at the resting angle and at face-on.
  // Solving once for the resting angle and reusing it through the warp is what left
  // the head off-centre when it turned to camera.
  const frameRest = {target: new THREE.Vector3(), R: 0};
  const frameFaceOn = {target: new THREE.Vector3(), R: 0};

  function solveFrame(theta, out) {
    const halfFov = (camera.fov * Math.PI) / 180 / 2;
    R = cloudRadius / Math.sin(halfFov); // safe starting point: nothing can clip
    scanBox.getCenter(frameTarget); // re-centre before re-solving (SCAN bounds, not geo's)

    for (let i = 0; i < FIT_PASSES; i++) {
      place(theta);
      const b = projectedBounds();

      // Slide the look-at point so the cloud's screen bounds straddle the centre.
      // An NDC offset converts to world units through the frame's visible size at
      // this distance: half-height is R·tan(fov/2), half-width that times the aspect.
      const halfH = R * Math.tan(halfFov);
      const halfW = halfH * camera.aspect;
      camera.matrixWorld.extractBasis(_right, _up, _v);
      frameTarget
        .addScaledVector(_right, ((b.minX + b.maxX) / 2) * halfW)
        .addScaledVector(_up, ((b.minY + b.maxY) / 2) * halfH);

      // Then scale the distance so the (now centred) cloud fits the frame. Whichever
      // axis overflows most decides it: on a wide window that's the height, and the
      // cloud fills top to bottom; on a tall narrow one it's the width, and the cloud
      // sits smaller with margin above and below.
      //
      // Fitting height alone — which is what this did first — pushed the face off both
      // sides of a phone, because a portrait frame is narrower than the cloud is wide.
      // NDC runs -1 to 1 on both axes, so the two reaches compare directly.
      const reach = Math.max((b.maxY - b.minY) / 2, (b.maxX - b.minX) / 2);
      if (reach) R *= reach / FILL;
    }

    out.target.copy(frameTarget);
    out.R = R;
  }

  // Both angles the camera ever sits at, solved together whenever the frame changes.
  // Two solves rather than one: cheap here (it only runs on a settled resize), and it
  // means the warp can interpolate between two correct framings instead of drifting
  // away from a single one.
  function fitRadius() {
    solveFrame(BASE, frameRest);
    solveFrame(WARP_FACE_ON, frameFaceOn);
    frameTarget.copy(frameRest.target);
    R = frameRest.R;
    solvePointerHeadroom();
  }

  // `phi` is a parameter and not the constant so the pointer can tilt the camera.
  // It DEFAULTS to PHI on purpose: the framing solve above calls this while measuring,
  // and a fit that moved with the cursor would re-frame the cloud every time the mouse
  // did — the fit has to describe one fixed viewpoint.
  function place(theta, phi = PHI) {
    camera.position.set(
      frameTarget.x + R * Math.sin(phi) * Math.sin(theta),
      frameTarget.y + R * Math.cos(phi),
      frameTarget.z + R * Math.sin(phi) * Math.cos(theta));
    camera.lookAt(frameTarget);
  }

  // ── Pointer parallax ──────────────────────────────────────────────────────
  // HAND-ADDED, not from the exporter — re-apply if hero.js is regenerated.
  //
  // The cursor turns the head. Not a tilt on a flat image: this moves the actual orbit
  // camera, so near points travel further across the frame than far ones and the face
  // genuinely rotates. It rides on top of the idle sweep rather than replacing it, so
  // the subject still breathes when nobody is moving a mouse.
  //
  // 1 = the face turns TOWARD the cursor, which is what suits a page that opens by
  // asking you a question. -1 pushes it away instead — the whole push/pull difference
  // is this sign.
  const POINTER_FOLLOW = 1;
  // Roughly 1.8× the first tuning (0.045 / 0.026, ~2.6°/1.5°), which read as barely
  // there. Still inside the 2.5°–5° band scaleFor's linearity was checked over, and
  // the headroom solver below caps either axis on a frame that hasn't the room.
  const POINTER_YAW = 0.08;    // ~4.6° either side at full deflection
  const POINTER_PITCH = 0.046; // ~2.6°
  // Seconds to close about two thirds of the gap to the cursor. The ease runs in the
  // render loop rather than the move handler: tracking the pointer rigidly reads as
  // jitter, and easing handler-side would step at whatever rate the mouse reports
  // instead of at frame rate.
  const POINTER_TAU = 0.16;
  // How near the frame edge ANY of this may push the cloud — sweep and pointer alike.
  // Not 1.0: a point has on-screen size the projected geometry knows nothing about, so
  // the outermost one would sit half cut at exactly the edge.
  const FRAME_LIMIT = 0.99;

  // MEASURED, not predicted — the same reasoning as the distance fit above. How far a
  // given yaw carries the cloud toward the frame edge depends on the aspect, on which
  // points happen to sit at the edges, and on the perspective at this distance. The
  // only reliable way to know is to project it and look.
  //
  // Three scales rather than one, because the headroom is nothing alike between them.
  // The fit binds on HEIGHT in a landscape window — the cloud reaches ~96% of the way
  // up the frame while using under half its width — so pitch is spending a margin that
  // yaw has in abundance, and one shared cap would throttle yaw to what pitch can
  // afford. On a frame with no room the scale falls to zero and that axis simply holds
  // still, which is the honest answer for a tall narrow window.
  let sweepScale = 1, pointerYawScale = 1, pointerPitchScale = 1;

  // Worst case at a given deflection from BASE, as a fraction of the frame half-size.
  // Both signs, since the cloud is not symmetric about the view axis and the tighter
  // side is the one that matters.
  function reachAt(dTheta, dPhi) {
    let reach = 0;
    for (const s of [-1, 1]) {
      place(BASE + s * dTheta, PHI + s * dPhi);
      const b = projectedBounds();
      reach = Math.max(reach,
        Math.abs(b.minX), Math.abs(b.maxX), Math.abs(b.minY), Math.abs(b.maxY));
    }
    return reach;
  }

  // Linear between a resting reach and the reach at full deflection. Checked across
  // 2.5°/3.5°/5°, where the growth is near enough straight to make anything cleverer
  // pointless.
  function scaleFor(rest, full) {
    if (full <= FRAME_LIMIT) return 1;
    return Math.max(0, Math.min(1, (FRAME_LIMIT - rest) / (full - rest)));
  }

  function solvePointerHeadroom() {
    // The sweep is capped first and the pointer is then measured ON TOP of the swept
    // extreme — the two stack, and a cursor held hard left while the sweep is also at
    // its left extreme is the frame that would actually clip.
    sweepScale = scaleFor(reachAt(0, 0), reachAt(ARC, 0));
    const swept = ARC * sweepScale;
    const sweptReach = reachAt(swept, 0);
    pointerYawScale = scaleFor(sweptReach, reachAt(swept + POINTER_YAW, 0));
    pointerPitchScale = scaleFor(sweptReach, reachAt(swept, POINTER_PITCH));
    place(BASE); // put the camera back where the fit left it
  }

  // Re-fitting is expensive — 37k points projected, four passes — and a ResizeObserver
  // fires every frame while a window edge is dragged. Two guards:
  //
  //  · the fit depends only on the ASPECT (fov is fixed), so a height-only change is
  //    skipped outright. That covers a mobile browser collapsing its address bar,
  //    which fires resize on every scroll and changes nothing about the framing.
  //  · when the aspect has genuinely changed, the fit is deferred until the size
  //    settles. The renderer and camera update immediately, so nothing looks broken
  //    mid-drag; the cloud simply holds its previous framing and re-frames once at
  //    the end, instead of once per frame.
  const REFIT_DELAY = 150;
  const ASPECT_EPSILON = 0.001; // below this, the framing wouldn't visibly move
  let fittedAspect = 0;
  let refitTimer = 0;

  function resize() {
    const w = container.clientWidth, hgt = container.clientHeight;
    if (!w || !hgt) return;

    renderer.setSize(w, hgt, false);
    camera.aspect = w / hgt;
    camera.updateProjectionMatrix();
    mat.uniforms.uScale.value = hgt * 0.5;

    if (Math.abs(camera.aspect - fittedAspect) < ASPECT_EPSILON) return;

    clearTimeout(refitTimer);
    // First fit runs now, so the cloud is framed on the very first frame rather than
    // arriving at the exported radius and jumping a beat later.
    if (!fittedAspect) refit();
    else refitTimer = setTimeout(refit, REFIT_DELAY);
  }

  function refit() {
    fitRadius();
    fittedAspect = camera.aspect;
  }

  const ro = new ResizeObserver(resize); ro.observe(container); resize();

  let raf = 0; const t0 = performance.now();
  let lastFrame = t0;
  // Pause when off-screen so a hero at the top of the page is not burning GPU
  // while someone reads the rest of the site.
  let visible = true;
  const io = new IntersectionObserver(function (e) { visible = e[0].isIntersecting; });
  io.observe(container);

  // Where the cursor is (target) and where the camera has eased to (now), each -1..1
  // across the hero box. HAND-ADDED, not from the exporter.
  const pointerTarget = {x: 0, y: 0};
  const pointerNow = {x: 0, y: 0};
  // Touch has no hover to parallax against, and a drag would yank the head about.
  const finePointer = matchMedia('(hover: hover) and (pointer: fine)');
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');

  // Listening on the WINDOW, not on this element. The h1 and the ask form are siblings
  // of the hero stacked over it, not children of it, so a listener here would fall
  // silent exactly where the cursor spends its time — over the question field.
  // Coordinates are still normalised against this element's box.
  function onPointerMove(e) {
    if (!visible || !finePointer.matches || reducedMotion.matches) return;
    // Read the box per move rather than caching it: it shifts with scroll as well as
    // with resize, and the browser already coalesces pointermove to about frame rate.
    const r = container.getBoundingClientRect();
    if (!r.width || !r.height) return;
    // Clamped, so a cursor far below the hero doesn't keep winding the head round.
    pointerTarget.x = Math.max(-1, Math.min(1, ((e.clientX - r.left) / r.width) * 2 - 1));
    // Vertical is one-sided: Jon may look up, never down. Looking down reads as
    // disengaged — eyes dropping away from the visitor — where up, and side to side,
    // read as attention. Which half to clamp follows from place(): the camera's height
    // is R·cos(phi), and the pointer ADDS to PHI, so a cursor above the midline (y > 0)
    // lowers the camera — Jon is seen from below and appears to look up, toward it —
    // while a cursor below raises the camera and he appears to look down. The lower
    // half is therefore clamped to 0 (the base pitch); only a cursor above the midline
    // moves the camera. Don't judge this from screenshots: the idle sweep shifts the
    // cloud more than the pitch does, and in a landscape window the headroom solver
    // scales the pitch close to nothing anyway.
    pointerTarget.y = Math.max(0, Math.min(1, 1 - ((e.clientY - r.top) / r.height) * 2));
  }

  // Back to centre when the cursor leaves the window or the tab loses focus, rather
  // than holding whatever turn it was mid-way through. No relatedTarget on a pointerout
  // means it left the document, not just one element.
  function recentre(e) { if (!e || !e.relatedTarget) { pointerTarget.x = 0; pointerTarget.y = 0; } }

  window.addEventListener('pointermove', onPointerMove, {passive: true});
  window.addEventListener('pointerout', recentre, {passive: true});
  window.addEventListener('blur', recentre);

  // Freeze for the page transition. That animation scales and fades the whole
  // document, so this canvas is inside a layer being recomposited every frame — and
  // we'd otherwise still be drawing 37k points into it at the same time, for a view
  // that's on its way off screen. The last frame stays up and scales with the rest of
  // the page, which is exactly what's wanted. One way only: the page is leaving.
  let shown = false; // set once the first frame has rendered, to trigger the fade-in
  let leaving = false;
  const onPageLeaving = () => { leaving = true; };
  document.addEventListener('page:leaving', onPageLeaving);

  // ── Warp out ──────────────────────────────────────────────────────────────
  // HAND-EDITED, not from the exporter — re-apply if hero.js is regenerated.
  //
  // The exit beat when a visitor asks their first question: the head TURNS TO CAMERA,
  // then comes apart — so the person acknowledges you and dissolves into the
  // conversation, rather than the section being switched off.
  //
  // Nothing new is loaded for this. `uAmpAll` is already in the vertex shader — it
  // displaces every point along its own direction, where `uAmp` only moves the ones
  // flagged as edges — and it has sat at 0 until now.
  //
  // (WARP_FACE_ON is declared with BASE further up, because the framing solve needs it.)
  const WARP_MS = 700;
  const WARP_TURN_UNTIL = 0.34; // the turn is the pause before the run
  //
  // THE FLY-THROUGH.
  //
  // The camera doesn't stop in front of the cloud, it goes THROUGH it. That's the
  // whole difference between this and what was here before: an approach that halts
  // and fades out is a dissolve, however fast you make it — you never cross anything,
  // so you never arrive anywhere. Passing the centre is what makes it travel.
  //
  // Measured as a multiple of the framing distance, so it holds at any viewport:
  //   1    where the camera rests
  //   0    the cloud's centre
  //  −0.6  well past it, cloud behind the camera, points streaking away either side
  const WARP_FLY_TO = -0.6;
  const WARP_FLY_FROM = 0.34; // starts as the turn lands, and doesn't let up
  // Curve exponent for the flight. Higher hangs back longer and then goes harder;
  // this is the sensation dial, more than the distance is.
  const WARP_FLY_POWER = 3.2;

  // The near plane has to come in with the camera. At the default 0.001 it's fine,
  // but the moment the camera is inside the cloud the nearest points are millimetres
  // away — anything nearer than this is clipped, and a too-large near plane would
  // punch a growing hole through the middle of the frame as you enter.
  const WARP_NEAR = 0.0005;

  // (No WARP_STREAK. Point size used to be multiplied up during the flight to stand in
  // for motion blur; it's gone — the shader's own 1/distance scaling does that as the
  // camera closes, and the staggered dissolve carries the coming-apart. See the note in
  // the flight block below.)

  // Only a light scatter now. The old exit needed the cloud to blow apart because
  // that was the only motion in it; here the camera supplies the movement, and a big
  // scatter actively fights it by clearing the points out of the flight path before
  // you reach them.
  const WARP_SCATTER = 0.18;
  const WARP_SCATTER_FROM = 0.15;
  const WARP_TURBULENCE = 0.04;

  // Where the staggered dissolve starts, as a fraction of the warp. After the turn
  // (WARP_TURN_UNTIL 0.34) on purpose: the face has to finish looking at you before it
  // starts coming apart. Everything from here to the end is points winking out.
  const WARP_DISSOLVE_FROM = 0.4;

  // The fade is now a CUT, not a dissolve. It waits until the camera is through and
  // the cloud is behind it, then takes the last sliver. Fading earlier would hide the
  // fly-through, which is the entire point of it.
  const WARP_FADE_FROM = 0.82;

  // ── Arrival ───────────────────────────────────────────────────────────────
  // HAND-ADDED, not from the exporter — re-apply if hero.js is regenerated.
  //
  // The reverse of the exit. warpOut drives uBurst 0 -> WARP_SCATTER to blow the cloud
  // apart; this runs it the other way, so the points fly IN from outside and settle
  // into the face. Same uniform, same shader path — nothing new to get wrong, and the
  // two beats rhyme: the cloud assembles when you arrive and scatters when you leave.
  //
  // Starts further out than the exit scatters to (0.35 vs 0.18): coming together needs
  // to be legible from the first frame, where the exit only has to be gone by the end.
  // Along the VIEW AXIS, not radially. Radial travel spreads the cloud sideways —
  // ear to ear — which reads as the head bursting outward. Sending every point along
  // the camera's own axis instead stretches it front-to-back, eyes through to the back
  // of the head, so the face reassembles out of depth rather than out of a splatter.
  //
  // Much smaller than a radial burst for the same apparent movement: one axis carries
  // the full displacement where a radial one splits it over every direction, and the
  // travel is straight at the camera, where perspective magnifies it hardest.
  const INTRO_MS = 1100;
  const INTRO_BURST = 0.55;
  // Points arrive slightly enlarged and shrink to size, which reads as motion blur on
  // the way in. The exit has no equivalent: there the camera moves, so the shader's
  // own 1/distance scaling grows the points for free. Here the camera is still and
  // the points do the travelling, so nothing grows them unless this does.
  const INTRO_STREAK = 1.8;
  let introStart = 0; // set on the first drawn frame, not at mount — see the loop

  let warping = false;
  let warpStart = 0;
  let warpDone = null;
  let warpFailsafe = 0;
  // Captured on the first frame of the flight and held for its duration; zero length
  // means "not flying yet". Reset when a warp starts, so a second one flies straight.
  const flightOrigin = new THREE.Vector3();
  const flightDir = new THREE.Vector3();
  const POINT_SIZE = mat.uniforms.uSize.value; // the resting size the intro shrinks to

  // Quadratic, not cubic. Cubic sat too close to zero for too long — at a fifth of the
  // way in it has moved less than a hundredth of the distance, which read as the
  // animation having stalled rather than as anticipation.
  const easeIn = (f) => f * f;
  // Decelerating, so the head settles into looking at you rather than snapping there.
  const easeOut = (f) => 1 - Math.pow(1 - f, 3);

  // Whoever gets there first wins; the other is cancelled.
  function finishWarp() {
    if (!warping) return;
    warping = false;
    clearTimeout(warpFailsafe);
    const done = warpDone;
    warpDone = null;
    if (done) done();
  }

  function warpOut(onComplete) {
    if (warping) { warpDone = onComplete || warpDone; return; }
    warping = true;
    warpStart = performance.now();
    // Drop the fade-in transition: the warp sets opacity every frame, and easing each
    // of those writes would smear the cut into a lag.
    renderer.domElement.style.transition = "none";
    warpDone = onComplete || null;
    flightDir.set(0, 0, 0); // re-capture the heading for this flight

    // Settle the arrival first. The warp drives uBurst from 0, so firing it mid-intro
    // would snap a still-assembling cloud inward before blowing it back out. Only
    // reachable by asking a question within INTRO_MS of the hero appearing, but the
    // fix is to finish the intro rather than to hope nobody is that quick.
    mat.uniforms.uBurst.value = 0;
    mat.uniforms.uSize.value = POINT_SIZE;
    mat.uniforms.uBurstAxis.value.set(0, 0, 0); // the exit scatters radially
    mat.uniforms.uReveal.value = 1;             // and does so at full opacity

    // The callback OPENS THE CONVERSATION, so it can't be left to the render loop
    // alone. rAF stops in a backgrounded tab, and the loop also skips its body when
    // the hero is scrolled out of view — either would strand a visitor on a hero
    // that has already faded, with no thread behind it. This guarantees the thread
    // arrives whether or not a single frame is drawn.
    clearTimeout(warpFailsafe);
    warpFailsafe = setTimeout(finishWarp, WARP_MS + 120);
  }

  (function loop() {
    raf = requestAnimationFrame(loop);
    const nowMs = performance.now();
    // Clamped hard: the loop stops entirely while the tab is hidden or the hero is
    // scrolled away, so the first frame back would otherwise carry a delta of seconds
    // and snap the pointer ease straight onto its target.
    const dt = Math.min(0.05, (nowMs - lastFrame) / 1000);
    lastFrame = nowMs;
    if (!visible || leaving) return;
    const t = (nowMs - t0) / 1000;
    mat.uniforms.uTime.value = t;
    let theta = BASE;
    if (MOTION === "spin") theta = BASE + t * 0.15;
    // sweepScale is 1 on anything landscape and only bites on a frame too narrow to
    // hold the full swing — see solvePointerHeadroom.
    else if (MOTION === "sweep") theta = BASE + Math.sin(t * 0.5 * SPEED) * ARC * sweepScale;

    // Exponential ease toward the cursor, expressed in seconds so it feels identical
    // at 60Hz and 120Hz. A fixed per-frame fraction would arrive twice as fast on a
    // 120Hz display, which is how the same number ends up feeling right on one machine
    // and snappy on another.
    const k = 1 - Math.exp(-dt / POINTER_TAU);
    pointerNow.x += (pointerTarget.x - pointerNow.x) * k;
    pointerNow.y += (pointerTarget.y - pointerNow.y) * k;

    if (warping) {
      const f = Math.min(1, (performance.now() - warpStart) / WARP_MS);

      // Turn to camera first, easing out so it settles rather than snapping.
      const turn = easeOut(Math.min(1, f / WARP_TURN_UNTIL));
      theta = BASE + (WARP_FACE_ON - BASE) * turn;

      // Carry the FRAMING round with the turn. Each angle has its own centre and its
      // own fitting distance — turning changes which points sit at the frame's edges —
      // so holding the resting values through the warp left the head off-centre by the
      // time it faced camera. Both were solved at fit time; this walks between them.
      frameTarget.lerpVectors(frameRest.target, frameFaceOn.target, turn);
      const framedR = frameRest.R + (frameFaceOn.R - frameRest.R) * turn;

      // Then come apart. Rebased so the scatter runs its full curve in the time it
      // has left, instead of starting part-way up it.
      const s = Math.max(0, (f - WARP_SCATTER_FROM) / (1 - WARP_SCATTER_FROM));
      const e = easeIn(s);
      // A light loosening, so the surface isn't rigid as you pass through it.
      mat.uniforms.uBurst.value = WARP_SCATTER * (s * s * s);
      mat.uniforms.uAmpAll.value = WARP_TURBULENCE * e;

      // The intro's staggered reveal, run backwards: uReveal walks 1 -> 0 so points
      // wink OUT one by one instead of the whole cloud fading as a sheet. Same uniform,
      // same per-point thresholds, same shader branch — the arrival and the departure
      // are now the same effect in opposite directions.
      //
      // The order reverses with it, which is what makes it read as an undo rather than
      // a repeat: a point's threshold is a fixed property of where it sits, so the last
      // points to arrive are the first to leave.
      //
      // Held at 1 until WARP_DISSOLVE_FROM so the turn plays out on a solid face — the
      // head has to look at you before it comes apart, not while.
      const dissolve = Math.max(0, (f - WARP_DISSOLVE_FROM) / (1 - WARP_DISSOLVE_FROM));
      mat.uniforms.uReveal.value = 1 - dissolve;

      // THE FLIGHT — a straight line along the camera's own heading, not a shrinking
      // orbit radius. Orbiting can't express this: the radius would have to pass
      // through zero, and at zero the camera sits exactly on the point it's aiming at,
      // so its orientation is undefined and the view snaps end over end. Flying means
      // holding a heading and travelling down it, which is what this does — position
      // moves, aim doesn't.
      const fly = Math.pow(Math.max(0, (f - WARP_FLY_FROM) / (1 - WARP_FLY_FROM)), WARP_FLY_POWER);
      R = framedR; // keep the orbit honest for the frames before the flight starts

      // Pull the near plane in with it. Once the camera is among the points the
      // closest are a hair away, and the default near plane would clip them — a hole
      // opening in the middle of the frame at exactly the moment you enter.
      const near = WARP_NEAR + (0.001 - WARP_NEAR) * (1 - fly);
      if (camera.near !== near) {
        camera.near = near;
        camera.updateProjectionMatrix();
      }

      // NO size curve here, deliberately. The vertex shader already divides point size
      // by distance (gl_PointSize = uSize * uScale / -mv.z), so flying INTO the cloud
      // enlarges every point on its own, and hard — `-mv.z` is heading for the near
      // plane. A multiplier on top was a third mechanism doing a job the projection
      // and the dissolve already cover between them, and it was what produced the fat
      // blobs on the last frames. uSize stays at POINT_SIZE for the whole warp.

      // A CUT, not a dissolve: it waits until the cloud is behind the camera. Opacity
      // is on the element, not the material — one composite rather than 37k per-point
      // alpha blends.
      const fade = Math.max(0, (f - WARP_FADE_FROM) / (1 - WARP_FADE_FROM));
      renderer.domElement.style.opacity = String(1 - easeIn(fade));
      if (f >= 1) finishWarp();

      place(theta); // sets the orbit position + aim for this frame

      if (fly > 0) {
        // Capture the heading ONCE, the first frame the flight starts — recomputing it
        // per frame against a target the camera is closing on would bend the path and
        // then reverse it on the way out. A flight is a straight line.
        if (!flightDir.lengthSq()) {
          flightOrigin.copy(camera.position);
          flightDir.copy(frameTarget).sub(camera.position).normalize();
        }
        // Travel far enough to end up WARP_FLY_TO of the framing distance beyond the
        // centre — so the cloud finishes behind the camera, not in front of it.
        const travel = framedR * (1 - WARP_FLY_TO) * fly;
        camera.position.copy(flightOrigin).addScaledVector(flightDir, travel);
        // Aim stays fixed down the heading. Looking back at the cloud would swing the
        // camera round as it passed, which reads as a stumble rather than a flight.
        _v.copy(camera.position).addScaledVector(flightDir, 1);
        camera.lookAt(_v);
      }

      renderer.render(scene, camera);
    } else {
      // Timed from the first DRAWN frame, not from mount. The loop doesn't run while
      // the tab is hidden or the hero is scrolled out of view, so timing from mount
      // could spend the whole animation before a single frame was ever on screen —
      // the visitor would arrive to a cloud that had already assembled without them.
      if (!introStart) {
        introStart = performance.now();
        // The HEAD's forward axis, not the camera's. Travel along the view axis is
        // nearly invisible — moving a point straight at the camera doesn't shift it
        // across the frame at all, it only makes it bigger, so the whole thing reads
        // as a zoom. This is the direction the face looks: the unit vector from the
        // cloud's centre to where the camera sits at WARP_FACE_ON, the yaw at which
        // the face is square to camera. At rest the camera is ~38° off that, which is
        // what turns the travel into visible movement across the frame.
        //
        // NEGATED, so the points start BEHIND the head and travel forward into the
        // face. Positive is out of the face, which sends them backwards as they
        // settle — the face dissolves away from you and the back of the head is what
        // reads as arriving.
        mat.uniforms.uBurstAxis.value.set(
          Math.sin(PHI) * Math.sin(WARP_FACE_ON),
          Math.cos(PHI),
          Math.sin(PHI) * Math.cos(WARP_FACE_ON),
        ).negate(); // set() is already unit length — sin²+cos² over the same PHI
      }
      const intro = Math.min(1, (performance.now() - introStart) / INTRO_MS);

      if (intro < 1) {
        // Decelerating, so the points rush in and ease into place rather than
        // arriving at a constant speed and stopping dead.
        const settle = easeOut(intro);
        mat.uniforms.uBurst.value = INTRO_BURST * (1 - settle);
        mat.uniforms.uSize.value = POINT_SIZE * (1 + INTRO_STREAK * (1 - settle));
        // Linear, NOT eased. The stagger is what makes this read, and easing it
        // compresses every point's threshold into the same instant at one end or the
        // other — which is the lockstep step-up the stagger exists to avoid.
        mat.uniforms.uReveal.value = intro;
      } else if (mat.uniforms.uBurst.value !== 0) {
        // Land on the exact resting values once, then stop touching them. The axis
        // goes back to zero so the exit gets its radial scatter, not this one.
        mat.uniforms.uBurst.value = 0;
        mat.uniforms.uSize.value = POINT_SIZE;
        mat.uniforms.uBurstAxis.value.set(0, 0, 0);
        mat.uniforms.uReveal.value = 1; // >= 1 short-circuits the reveal branch
      }

      // The cursor rides ON TOP of the sweep, and only in this branch. The warp drives
      // theta and the framing outright — letting the pointer tug at the camera while
      // it turns to face you and flies through the cloud would bend the flight path,
      // which is a straight line by design.
      place(theta - POINTER_FOLLOW * POINTER_YAW * pointerYawScale * pointerNow.x,
            PHI + POINTER_FOLLOW * POINTER_PITCH * pointerPitchScale * pointerNow.y);
      renderer.render(scene, camera);
    }

    // First frame is on screen — let it in.
    if (!shown) {
      shown = true;
      renderer.domElement.style.opacity = "1";
    }
  })();

  return {
    warpOut,
    dispose() {
      cancelAnimationFrame(raf); ro.disconnect(); io.disconnect();
      document.removeEventListener('page:leaving', onPageLeaving);
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerout', recentre);
      window.removeEventListener('blur', recentre);
      renderer.domElement.removeEventListener('webglcontextrestored', onContextRestored);
      clearTimeout(refitTimer);   // a deferred fit must not run against a dead renderer
      clearTimeout(warpFailsafe); // nor a warp completion
      geo.dispose(); mat.dispose(); renderer.dispose();
      renderer.domElement.remove();
    }
  };
}